"""Algorithm A: orbit partition of a finite model by union-find.

Given a carrier {0, ..., n-1} and a list of generating symmetries, compute the
partition of the carrier into orbits of the group they generate, and from it the
meaning-loss exponent L(M) = |M| - #orbits.
"""

from __future__ import annotations

from typing import Dict, FrozenSet, List, Sequence, Set, Tuple

Perm = Tuple[int, ...]
Orbit = FrozenSet[int]


def orbit_partition(n: int, generators: Sequence[Perm]) -> List[Orbit]:
    """Partition {0,...,n-1} into orbits of the group generated by `generators`.

    Only the generators are needed: the orbit relation is the reflexive,
    symmetric, transitive closure of `x ~ g.x` for g ranging over generators.
    Complexity: O(n * |S| * alpha(n)) for |S| generators, alpha inverse-Ackermann.
    """
    parent: List[int] = list(range(n))

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]     # path compression
            x = parent[x]
        return x

    def union(x: int, y: int) -> None:
        rx, ry = find(x), find(y)
        if rx != ry:
            parent[max(rx, ry)] = min(rx, ry)

    for g in generators:
        for x in range(n):
            union(x, g[x])

    buckets: Dict[int, Set[int]] = {}
    for x in range(n):
        buckets.setdefault(find(x), set()).add(x)
    return sorted((frozenset(b) for b in buckets.values()), key=lambda o: min(o))


def meaning_loss(n: int, generators: Sequence[Perm]) -> int:
    """The meaning-loss exponent L(M) = |M| - #orbits."""
    return n - len(orbit_partition(n, generators))


def duplicate_count(n: int, generators: Sequence[Perm]) -> int:
    """The duplicate count sum_orbits (|O| - 1), provably equal to L(M)."""
    return sum(len(o) - 1 for o in orbit_partition(n, generators))


if __name__ == "__main__":
    # The 3-path 0 - 1 - 2: the only non-identity symmetry is the endpoint swap.
    endpoint_swap: Perm = (2, 1, 0)
    parts = orbit_partition(3, [endpoint_swap])
    print("orbits of the 3-path:", [sorted(o) for o in parts])
    print("meaning-loss exponent:", meaning_loss(3, [endpoint_swap]))
    print("duplicate count      :", duplicate_count(3, [endpoint_swap]))

    # A 4-cycle 0-1-2-3-0: the rotation generates a single orbit.
    rotation: Perm = (1, 2, 3, 0)
    print("orbits of the 4-cycle:", [sorted(o) for o in orbit_partition(4, [rotation])])
    print("meaning-loss exponent:", meaning_loss(4, [rotation]))
